={{ $json.campanha.mensagens.map(m => {
  const data = new Date();
  data.setDate(data.getDate() + m.dia);
  return `${String(data.getDate()).padStart(2, '0')}/${String(data.getMonth() + 1).padStart(2, '0')}`;
}).join('\n') }}

